import React, { useState } from 'react';
import { createTask } from '../services/api';

const AddTaskModal = ({ onClose, onTaskAdded }) => {
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [status, setStatus] = useState('To Do');
  const [screenshots, setScreenshots] = useState([]);
  const [error, setError] = useState(null);

  const handleFileChange = (e) => {
    setError(null); // Clear previous error
    const files = Array.from(e.target.files);

    const validFiles = files.filter((file) => {
      const isImage = file.type.startsWith('image/');
      const isUnder2MB = file.size <= 2 * 1024 * 1024; // 2MB
      if (!isImage) {
        setError('Only image files are allowed.');
      } else if (!isUnder2MB) {
        setError('File size must be less than 2MB.');
      }
      return isImage && isUnder2MB;
    });

    if (validFiles.length > 0) {
      const fileNames = validFiles.map((file) => file.name);
      setScreenshots(fileNames);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (error) return; // Prevent submission if there's an error
    const newTask = { title, description, status, screenshots };
    const response = await createTask(newTask);
    onTaskAdded(response.data);
    onClose();
  };

  return (
    <div className="modal">
      <form onSubmit={handleSubmit} className="modal-form">
        <h2>Add New Task</h2>
        <input
          type="text"
          placeholder="Title"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          required
          className="form-input"
        />
        <textarea
          placeholder="Description"
          value={description}
          onChange={(e) => setDescription(e.target.value)}
          className="form-input"
        />
        <select
          value={status}
          onChange={(e) => setStatus(e.target.value)}
          className="form-input"
        >
          <option value="To Do">To Do</option>
          <option value="In Progress">In Progress</option>
          <option value="Done">Done</option>
        </select>
        <input
          type="file"
          multiple
          onChange={handleFileChange}
          className="form-input"
          accept="image/*"
        />
        {error && <p className="error">{error}</p>}
        <div className="form-actions">
          <button className="btn-primary" type="submit">
            Add Task
          </button>
          <button className="btn-secondary" type="button" onClick={onClose}>
            Cancel
          </button>
        </div>
      </form>
    </div>
  );
};

export default AddTaskModal;
